package com.print.kiosk.controller;
import com.print.kiosk.dto.request.VerifyCashPaymentRequest;import com.print.kiosk.dto.response.*;import com.print.kiosk.service.interfaces.CashPaymentService;import jakarta.validation.Valid;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/print-requests") public class PublicPaymentController{private final CashPaymentService service;public PublicPaymentController(CashPaymentService s){service=s;}@GetMapping("/payment-options")public ResponseEntity<List<PaymentOptionResponse>> options(){return ResponseEntity.ok(service.getPaymentOptions());}@PostMapping("/{trackingNumber}/payments/cash")public ResponseEntity<PaymentResponse> cash(@PathVariable String trackingNumber,@Valid @RequestBody VerifyCashPaymentRequest request){return ResponseEntity.ok(service.verifyCash(trackingNumber,request));}}